// Детектор «разговора не было». Одна функция на две ноды: agent-facts-assembler и b4.5,
// по образцу isAiComment — детерминированная, без обращений к сети и модели.
//
// Зачем. Транскрипт приписывает клиенту любой голос на той стороне. Если ответил
// автоответчик оператора, виртуальный помощник или человек сказал только «алло», в фактах
// появляется реплика с actor=client, и судья считает это контактом с клиентом. На живой
// сделке 119215 из двух таких звонков (11 и 6 секунд) вышел вердикт «неправомерен, закрыли
// при доступном клиенте» и ложная ошибка «причина "не выходит на связь" не соответствует фактам».
//
// Существующий detectVoicemail в agent-facts-assembler ловит часть случаев, но его списки
// не покрывают фразы операторов связи, виртуальных помощников и пустые приветствия.
// Этот детектор — второй слой, он добирает остальное.
//
// ГЛАВНЫЙ ПРИНЦИП: живые слова клиента важнее машинного признака. Если после вырезания
// машинных фраз, приветствий и обрывков остался осмысленный текст — разговор был, и звонок
// не помечается, даже если в начале записи говорил робот дозвона.
//
// Списки составлены по фактическим транскриптам 1591 короткого звонка и по стоп-листу системы
// обзвона (tasks/2026-09-30-robot-phrases.txt, 564 фразы). Стоп-лист взят не целиком:
// боты-«секретари» имитируют людей, и две трети его фраз может сказать живой клиент
// («очень дорого выходит», «перезвоните через пару часов»). Такие фразы самостоятельным
// признаком не считаются — иначе теряются живые отказы.

// ── пороги ──────────────────────────────────────────────────────────────────

// Выше этой длительности разговор считаем состоявшимся и детектор не применяем.
var NOTALK_MAX_SEC = 20;

// Поле длительности ненадёжно: у 261 звонка стоит 0 секунд, причём у 137 из них транскрипт
// длиннее 200 символов. При нулевой длительности судим по длине транскрипта.
var NOTALK_ZERO_SEC_CHARS = 200;

// Остаток текста после вырезания машинных фраз, приветствий и обрывков: больше этого —
// значит клиент сказал что-то своё.
var NOTALK_MEANINGFUL_CHARS = 12;

// Остаток реплики МЕНЕДЖЕРА для ветки «клиент сказал только приветствие». Если менеджер
// говорил содержательно, разговор был, даже когда в NOTALK_PURPOSE нет подходящих слов.
// Записи двухканальные: в канал менеджера попадают и сообщения оператора связи до ответа
// абонента, поэтому их нужно вырезать перед оценкой.
//
// Правило применяется ТОЛЬКО когда клиент сказал что-то помимо приветствия — пусть и коротко,
// как «это мой номер» в сделке 96701. Если клиент ограничился «Алло», разговора не было, даже
// когда менеджер говорил содержательно: так выглядит обрыв связи (сделка 109997, менеджер
// «связь прерывается… вас не слышно?»).
var NOTALK_MANAGER_REST_CHARS = 15;

// ── списки ──────────────────────────────────────────────────────────────────

// Фразы систем дозвона. Звучат ДО того, как трубку сняли, поэтому сами по себе ничего не
// значат: после них мог ответить и настоящий клиент. Вырезаются как шум.
var NOTALK_DIALING = [
  'оставайтесь на линии', 'продолжаем дозваниваться', 'продолжаю дозвон', 'должны дозваниваться',
  'дозваниваться до абонента', 'ожидайте ответа', 'не отключайтесь', 'продолжаю вызов',
  'запись разговоров активирована', 'запись разговора активирована', 'запись разговоров'
];

// ГРУППА A. Однозначно машина: сообщения оператора связи, голосовая почта, самоназвание бота.
// Достаточно одной фразы. Проверено: слова «ассистент», «помощник», «голосовой» в коротких
// звонках встречаются только у роботов (62, 34 и 74 раза из 1591).
var NOTALK_MACHINE = [
  // абонент недоступен — сообщения оператора
  'абонент', 'абоненту', 'вызываемый', 'вне зоны действия', 'телефон выключен',
  'телефон разряжен', 'телефон занят', 'не может ответить', 'может ответить на ваш звонок', 'не берет трубку',
  'не в сети', 'не на связи', 'недоступен', 'не доступен', 'линия занята', 'линия абонента',
  'номер не существует', 'сеть перегружена', 'аппарат вызываемого',
  'попробуйте перезвонить', 'перезвонить позднее', 'бесплатное смс', 'отправить бесплатное',
  'консультация оператора', 'на удержание', 'перенаправлен на', 'звонок был перенаправлен',
  // проверено на выгрузке: «не отвечает» в коротких звонках встречается только у машины
  'не отвечает', 'номер не отвечает',
  // голосовая почта
  'голосовая почта', 'голосовой почтовый', 'почтовый ящик', 'после звукового сигнала',
  'после сигнала', 'оставьте сообщение', 'оставить сообщение', 'запишите сообщение',
  'длительность сообщения', 'сообщение улетело', 'сообщение отправлено', 'сообщение готово',
  'сообщение достигло',
  // самоназвание бота и антиспам-сервисы
  'автоответчик', 'виртуальн', 'ассистент', 'помощник', 'помошник', 'секретар', 'голосовой',
  'защитник', 'умный бот', 'защита от спама', 'антиспам', 'я не человек', 'я программа',
  // передача сообщения ботом. Одиночное «передам» намеренно не берём: живой клиент скажет
  // «я передам мужу». В данных такие фразы всегда идут рядом с самоназванием бота.
  'что передать', 'что нужно передать', 'передам сообщение', 'передам ваше сообщение',
  'передам ему ваше сообщение', 'все от вас передам', 'сохраню и передам', 'запишу и передам',
  // проверка звонящего ботом
  'знакомы с абонентом', 'личному или деловому', 'личный или деловой',
  'с какой целью звоните', 'с какой целью', 'по какому поводу вы звоните',
  'озвучьте что', 'скажите что нужно',
  // технические подсказки
  'тоновый', 'тональн', 'пин код', 'для соединения нажмите', 'наберите добавочный',
  // бот сам говорит, что абоненту неудобно. Только полный шаблон: «мне сейчас неудобно
  // разговаривать» — живой клиент, его метить нельзя.
  'абоненту пока неудобно', 'абоненту сейчас неудобно', 'абоненту неудобно',
  // англоязычные сообщения оператора
  'not available', 'please try again', 'the number is', 'at the moment', 'try again later',
  'switched off'
];

// ГРУППА B. Шутки и отговорки ботов-«секретарей», которых живой клиент продавцу окон
// не скажет. Достаточно одной фразы.
var NOTALK_BOT_SMALLTALK = [
  'робот или человек', 'живой человек или робот', 'живой человек или автоответчик',
  'человек или компьютер', 'вы точно человек', 'вы случайно не робот', 'вы живой человек',
  'единорог', 'в слова сыграем', 'в слова поиграем', 'чур первый', 'в бар спамер',
  'не спамер', 'не спамеры', 'руки крюки', 'рюки крюки', 'век бы с вами',
  'одновременно положим трубки', 'не молчите лучшее'
];

// Длинные фразы целиком — только их ищем в реплике менеджера. Записи двухканальные, стороны
// не путаются: сообщения оператора связи звучат до ответа абонента и слышны на канале
// менеджера. Искать там отдельные слова нельзя: у менеджера «я прослушала ваш голосовой» —
// живой разговор (сделка 118715).
var NOTALK_MACHINE_IN_MANAGER = [
  'абонент сейчас не может ответить', 'абонент не может ответить',
  'абонент пока не может', 'абонент не берет трубку', 'абонент недоступен',
  'оставьте сообщение после сигнала', 'оставьте сообщение после звукового сигнала',
  'вне зоны действия сети', 'телефон выключен или находится',
  'вызываемый абонент не может', 'я виртуальный помощник', 'я виртуальный ассистент',
  'я голосовой помощник', 'я голосовой ассистент'
];

// Системные фразы, которые попадают в канал менеджера от телефонии, а не от человека.
var NOTALK_MANAGER_SYSTEM = [
  'пожалуйста подождите завершение обработки', 'подождите завершение обработки',
  'завершение обработки', 'пожалуйста подождите', 'идет соединение', 'соединяю'
];

// Менеджер сам говорит, что связь не установилась. Если при этом клиент успел сказать только
// «алло», предложение до него не дошло, сколько бы менеджер ни говорил: разговора не было.
// Это отличает обрыв связи (сделка 109997) от обычного «менеджер назвал цель, клиент услышал».
var NOTALK_BAD_LINE = [
  'связь прерывается', 'связь прервалась', 'связь барахлит', 'вас не слышно',
  'не слышно', 'плохо слышно', 'вы меня слышите', 'ничего не слышно', 'вы тут'
];

// Трубку снял не клиент: секретарь, родственник, не тот номер.
var NOTALK_NOT_CLIENT = [
  // Полный шаблон идёт первым: после его вырезания остаётся только приветствие.
  'сейчас нет вы по какому вопросу', 'сейчас нет вы по какому',
  'его сейчас нет', 'ее сейчас нет', 'нет на месте',
  'кого вам', 'не туда попали', 'вы не туда', 'ошиблись номером', 'номером ошиблись'
];

// Пустые реплики: приветствия и подтверждения, из которых нельзя понять, включился ли клиент
// в разговор. Вырезаются как отдельные фразы.
var NOTALK_GREETING = [
  'алло', 'аллло', 'ало', 'але', 'здравствуйте', 'здрасьте', 'приветствую', 'привет',
  'добрый день', 'добрый вечер', 'доброе утро', 'добрый',
  'я вас слушаю', 'слушаю вас', 'слушаю', 'говорите пожалуйста', 'говорите',
  'по какому вопросу звоните', 'по какому вопросу', 'по какому поводу', 'кто это',
  'продолжайте', 'на связи',
  'да да да', 'да да', 'да', 'нет', 'ага', 'угу', 'ммм', 'мм', 'э', 'а', 'ну',
  'пожалуйста', 'спасибо', 'что', 'простите', 'извините', 'секунду', 'минуту',
  'до свидания', 'всего доброго', 'всего хорошего'
];

// Обрывки машинных сообщений, которые остаются после вырезания фраз по подстроке.
// Без них остаток выглядит содержательным («его телефон», «если хотите», «возможно»).
var NOTALK_DEBRIS = [
  'его', 'ее', 'телефон', 'звонок', 'на ваш', 'сети', 'зоны', 'действия', 'возможно',
  'если хотите', 'сейчас', 'пока', 'вам', 'вы', 'или', 'находится', 'сообщение',
  'позднее', 'позже', 'но', 'и', 'в', 'с', 'на', 'не', 'это', 'я', 'он', 'она',
  'потому что', 'разговаривать', 'попробуй', 'был', 'была', 'было', 'можете', 'ящик'
];

// Слова, по которым видно, что менеджер назвал цель звонка или хотя бы представился.
// Если назвал — клиент снял трубку и услышал предложение, звонок остаётся контактом.
var NOTALK_PURPOSE = [
  // продукт и этапы сделки
  'окн', 'окош', 'остекл', 'балкон', 'двер', 'лодж', 'перегород', 'витраж',
  'замер', 'расчет', 'смет', 'стоимост', 'цена', 'цены', 'монтаж', 'установк',
  'заявк', 'заказ', 'договор', 'предложени', 'акци', 'скидк',
  // компания
  'динал', 'завод', 'компани',
  // менеджер представился или обозначил повод
  'менеджер', 'меня зовут', 'это ирина', 'это ольга', 'это марина', 'это мария',
  'вас беспокоит', 'вам удобно', 'удобно разговаривать', 'звоню по', 'звоню из',
  'звоню уточнить', 'я вам звонила', 'я вам звонил', 'мы с вами', 'по поводу',
  'обращались', 'уточнить', 'напомнить', 'подтвердить', 'согласовать',
  'отправил', 'отправля', 'считали', 'ранее'
];

// ── функции ─────────────────────────────────────────────────────────────────

function notalkNormalize(text) {
  if (!text) return '';
  return String(text)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[.,!?;:()"«»\-–—'"]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Вырезает фразы по подстроке. Длинные первыми, иначе короткая съест часть длинной
// и оставит мусор.
function notalkStripList(norm, list) {
  var sorted = list.slice().sort(function (a, b) { return b.length - a.length; });
  var rest = ' ' + norm + ' ';
  for (var i = 0; i < sorted.length; i++) {
    while (rest.indexOf(sorted[i]) !== -1) rest = rest.split(sorted[i]).join(' ');
  }
  return rest.replace(/\s+/g, ' ').trim();
}

// Вырезает фразы как отдельные слова, а не подстроки: «да» не должно съесть «давайте».
function notalkStripWords(norm, list) {
  var sorted = list.slice().sort(function (a, b) { return b.length - a.length; });
  var rest = ' ' + norm + ' ';
  for (var i = 0; i < sorted.length; i++) {
    var needle = ' ' + sorted[i] + ' ';
    while (rest.indexOf(needle) !== -1) rest = rest.split(needle).join(' ');
  }
  return rest.replace(/\s+/g, ' ').trim();
}

function notalkHit(norm, list) {
  for (var i = 0; i < list.length; i++) {
    if (norm.indexOf(list[i]) !== -1) return list[i];
  }
  return null;
}

// Моно-режим: стерео не распозналось, и весь звонок расшифрован одним потоком «Говорящий:».
// В базе таких 296 из 4226. Стороны в них не разделены (весь текст падает в канал менеджера),
// поэтому судить, кто что сказал, нельзя. Метим только если ВЕСЬ текст — фразы робота,
// оператора и приветствия. Остался живой текст — отдаём судье, пусть читает.
function detectNoConversationMono(wholeText, durationSec) {
  var wn = notalkStripList(notalkNormalize(wholeText), NOTALK_DIALING);
  wn = notalkStripList(wn, NOTALK_MANAGER_SYSTEM);

  var machine = notalkHit(wn, NOTALK_MACHINE) || notalkHit(wn, NOTALK_BOT_SMALLTALK);
  var notClient = notalkHit(wn, NOTALK_NOT_CLIENT);

  var rest = notalkStripList(wn, NOTALK_MACHINE);
  rest = notalkStripList(rest, NOTALK_BOT_SMALLTALK);
  rest = notalkStripList(rest, NOTALK_NOT_CLIENT);
  rest = notalkStripWords(rest, NOTALK_GREETING);
  rest = notalkStripWords(rest, NOTALK_DEBRIS);

  if (rest.length > NOTALK_MEANINGFUL_CHARS) return null;
  if (machine) return { reason: 'machine', matched: machine, rest: rest, mono: true, duration_sec: durationSec };
  if (notClient) return { reason: 'not_client', matched: notClient, rest: rest, mono: true, duration_sec: durationSec };
  return { reason: 'greeting_only', matched: null, rest: rest, mono: true, duration_sec: durationSec };
}

// Возвращает null, если разговор состоялся, либо объект с причиной.
// isMono — признак моно-записи: в проде это наличие «Говорящий:» в отформатированном транскрипте.
function detectNoConversation(clientText, managerText, durationSec, isMono) {
  var cnRaw = notalkNormalize(clientText);
  var mn = notalkNormalize(managerText);

  // Транскрипта нет вообще: оба канала пусты. Анализировать нечего, и утверждать
  // «прозвучало только приветствие» мы не вправе — мы просто не знаем, что было в записи.
  // Такой звонок отдаём сборщику фактов: он скажет честно «запись есть, но не распознана»
  // либо «записи нет». До этой правки 25 коротких звонков без текста получали
  // greeting_only и шли судье как доказанное отсутствие разговора.
  if (!cnRaw && !mn) return null;

  // Короткий ли звонок. При нулевой длительности поле не значит ничего — судим по транскрипту.
  var isShort;
  if (durationSec === 0 || durationSec === null || typeof durationSec !== 'number') {
    isShort = (cnRaw.length + mn.length) <= NOTALK_ZERO_SEC_CHARS;
  } else {
    isShort = durationSec <= NOTALK_MAX_SEC;
  }
  if (!isShort) return null;

  // Моно-запись разбираем отдельно: делить текст по сторонам нельзя.
  if (isMono) return detectNoConversationMono((clientText || '') + ' ' + (managerText || ''), durationSec);

  // Шум систем дозвона убираем сразу: он звучит до ответа.
  var cn = notalkStripList(cnRaw, NOTALK_DIALING);

  var machine = notalkHit(cn, NOTALK_MACHINE)
    || notalkHit(cn, NOTALK_BOT_SMALLTALK)
    || notalkHit(mn, NOTALK_MACHINE_IN_MANAGER);
  var notClient = notalkHit(cn, NOTALK_NOT_CLIENT);

  // Что осталось от реплики клиента, если убрать машинные фразы, приветствия и обрывки.
  var rest = notalkStripList(cn, NOTALK_MACHINE);
  rest = notalkStripList(rest, NOTALK_BOT_SMALLTALK);
  rest = notalkStripList(rest, NOTALK_NOT_CLIENT);
  rest = notalkStripWords(rest, NOTALK_GREETING);
  rest = notalkStripWords(rest, NOTALK_DEBRIS);

  // Живые слова клиента важнее машинного признака: робот мог говорить в начале записи,
  // а потом ответил настоящий клиент.
  if (rest.length > NOTALK_MEANINGFUL_CHARS) return null;

  // Ответила машина или трубку снял не клиент — разговора с клиентом не было, даже если
  // менеджер успел назвать цель: он говорил с автоответчиком или секретарём.
  if (machine) return { reason: 'machine', matched: machine, rest: rest, duration_sec: durationSec };
  if (notClient) return { reason: 'not_client', matched: notClient, rest: rest, duration_sec: durationSec };

  // Клиент ограничился приветствием. Сначала смотрим, не жалуется ли менеджер на связь:
  // тогда предложение до клиента не дошло, даже если цель звонка была названа.
  var badLine = notalkHit(mn, NOTALK_BAD_LINE);
  if (badLine) return { reason: 'bad_line', matched: badLine, rest: rest, duration_sec: durationSec };

  // Если менеджер назвал цель — клиент снял трубку и услышал предложение, это контакт.
  // Если менеджер молчал — звонок сорвался на нашей стороне.
  if (notalkManagerNamedPurpose(mn)) return null;

  // Слов из NOTALK_PURPOSE может не быть, а разговор всё равно состоялся. Смотрим, что
  // осталось от реплики менеджера, если убрать системные фразы телефонии и приветствия.
  var mgrRest = notalkStripList(mn, NOTALK_DIALING);
  mgrRest = notalkStripList(mgrRest, NOTALK_MANAGER_SYSTEM);
  mgrRest = notalkStripList(mgrRest, NOTALK_MACHINE_IN_MANAGER);
  mgrRest = notalkStripWords(mgrRest, NOTALK_GREETING);
  mgrRest = notalkStripWords(mgrRest, NOTALK_DEBRIS);
  if (rest.length > 0 && mgrRest.length > NOTALK_MANAGER_REST_CHARS) return null;

  return { reason: 'greeting_only', matched: null, rest: rest, manager_rest: mgrRest, duration_sec: durationSec };
}

function notalkManagerNamedPurpose(mn) {
  return notalkHit(mn, NOTALK_PURPOSE);
}
